import { Voronoi, type VoronoiProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#3a3a5c", "#52527a"];

interface ShaderVoronoiProps
  extends Omit<VoronoiProps, "frame" | "ref"> {}

function ShaderVoronoiBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  colorGap = "#12121a",
  distortion = 0.4,
  gap = 0.04,
  glow = 0,
  className,
  ...rest
}: ShaderVoronoiProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-voronoi"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Voronoi
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        colorGap={colorGap}
        distortion={distortion}
        gap={gap}
        glow={glow}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  distortion: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.4,
    description: "Distortion",
    hiddenFromList: false,
  },
  gap: {
    type: "number",
    min: 0,
    max: 0.2,
    step: 0.01,
    default: 0.04,
    description: "Gap",
    hiddenFromList: false,
  },
  glow: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0,
    description: "Glow",
    hiddenFromList: false,
  },
  colorGap: {
    type: "color",
    default: "#12121a",
    description: "Gap Color",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","distortion","gap","glow","colorGap"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  distortion: 0.4,
  gap: 0.04,
  glow: 0,
  colorGap: "#12121a",
};

type ShaderVoronoiElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderVoronoiBase>;

const ShaderVoronoiInner = forwardRef<
  HTMLDivElement,
  ShaderVoronoiElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderVoronoi>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderVoronoiBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderVoronoiBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderVoronoi = Interactive.withSchema({
  Component: ShaderVoronoiInner,
  componentName: "<ShaderVoronoi>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
